// 1. PRE-PROCESO: normalizar + construir el prompt del agente
const input = $input.all();
if (!input.length) return [];
const d = input[0].json;

const clean = (v) => String(v || '').trim();
const msg = clean(d.message);
const name = clean(d.name);
const email = clean(d.email).toLowerCase();
if (!msg) return [];

// Contenido del negocio embebido (contexto anclado, sin inventar)
const systemPrompt = 'Eres el recepcionista de Jonathan Esteban, un tecnico de
soporte informatico en Barcelona. Tu trabajo: LEER los mensajes entrantes
y CLASIFICARLOS antes de decidir si merecen respuesta.

SERVICIOS REALES (no inventes otros):
- Helpdesk N1
- Mantenimiento y Reparacion de PC
- Instalacion de Sistemas
- Diagnostico y Configuracion de Redes
- Soporte Ofimatico y Migracion
- Licencias Originales

CONDICIONES REALES: garantia de 15 dias, respuesta habitual en menos de 24h,
servicio en Barcelona.

REGLAS DE ORO (clasificacion de confianza - NO respondas a todo):
1. Si el mensaje pide un servicio, un presupuesto o cuenta una incidencia -> LEAD_REAL.
2. Si huele a fraude (pago por adelantado, urgencia falsa, enlaces raros,
   "soy un oficial", cifras extranas, promesas de dinero facil) -> FRAUDE
   y NUNCA propongas responder.
3. Si es personal/amigo/spam/irrelevante -> NO_COMERCIAL y NO respondas.
4. Si piden algo que no esta en tus datos (precio muy raro, garantia que
   no das) -> DUDA y NO inventes: deriva al humano.
5. Si es ambiguo/corto/otro idioma -> AMBIGUO con borrador conservador.

FORMATO DE SALIDA - SOLO JSON, sin markdown, sin texto extra:
{
  "clasificacion": "LEAD_REAL | FRAUDE | NO_COMERCIAL | DUDA | AMBIGUO",
  "justificacion": "una linea explicando por que",
  "servicio": "servicio detectado o null",
  "borrador": "respuesta en espanol, cercana y sin jerga, SOLO si
  clasificacion=LEAD_REAL o AMBIGUO; si no, cadena vacia",
  "pedir_datos": ["campos que faltan, p.ej. que equipo y desde cuando"]
}';

return [{
  json: {
    source: d.source || 'web-form',
    name, email, subject: clean(d.subject),
    message: msg,
    consentWhatsapp: !!d.consentWhatsapp,
    submittedAt: d.submittedAt || new Date().toISOString(),
    systemPrompt,
    userMessage: 'Mensaje de ' + (name || 'un visitante') + ' (' + email + '):
Asunto: ' + (clean(d.subject) || 'sin asunto') + '
Mensaje: ' + msg.slice(0, 3500)
  }
}];

// 3. CLASIFICACION: parsear el JSON que devolvio el LLM y decidir la ruta
const items = $input.all();
if (!items.length) return [];
const ai = items[0].json;
const content = ai.choices?.[0]?.message?.content || ai.output || '{}';

let parsed = {};
try { parsed = JSON.parse(content); } catch {
  const m = content.match(/{[\s\S]*}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch {} }
}

const cls = String(parsed.clasificacion || 'AMBIGUO').toUpperCase();
const leading = ['LEAD_REAL', 'AMBIGUO'].includes(cls);

return [{
  json: {
    ...items[0].json,
    clasificacion: cls,
    justificacion: parsed.justificacion || '',
    servicio: parsed.servicio || '',
    borrador: leading ? String(parsed.borrador || '') : '',
    pedir_datos: Array.isArray(parsed.pedir_datos) ? parsed.pedir_datos : [],
    respondible: leading,
    raw_clasificado: parsed
  }
}];

// 4. APROBACION: montar el aviso para Telegram con el borrador
const items = $input.all();
if (!items.length) return [];
const d = items[0].json;

const header = d.clasificacion === 'FRAUDE'
  ? '⚠️ FRAUDE detectado — NO responder'
  : d.clasificacion === 'NO_COMERCIAL'
    ? '🗑️ No comercial / spam — NO responder'
    : '📩 Nuevo lead — revisar borrador';

const lines = [
  header,
  'De: ' + d.name + ' <' + d.email + '>',
  'Asunto: ' + (d.subject || '—'),
  'Servicio: ' + (d.servicio || '—'),
  '',
  'Mensaje: ' + d.message.slice(0, 600)
];
if (['LEAD_REAL', 'AMBIGUO'].includes(d.clasificacion) && d.borrador) {
  lines.push('', '--- Borrador ---', d.borrador);
}

return [{ json: { ...d, telegramText: lines.join('\n'), aprobar: ['LEAD_REAL', 'AMBIGUO'].includes(d.clasificacion) } }];
